describe('Product Sorting by Price', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
    cy.get('[data-testid="login-container"]').click();
    cy.get('[data-testid="username"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="page-wrapper"]').should('be.visible');
  });

  it('should sort products by price in ascending order when selecting "lohi" option', () => {
    // Verify initial state
    cy.get('[data-testid="inventory-container"]').should('be.visible');
    cy.get('[data-testid="inventory-item-price"]').should('contain', '$');

    // Intercept API call to get products
    cy.intercept('GET', '/api/products').as('getProducts');
    cy.wait('@getProducts');

    // Verify products are displayed
    cy.get('[data-testid="inventory-item-name"]').should('have.length.greaterThan', 0);

    // Click the sort dropdown and select "lohi" option
    cy.get('[data-testid="product-sort-container"]').click();
    cy.get('[data-testid="sort-option-lohi"]').click();

    // Verify products are now sorted by price in ascending order
    cy.get('[data-testid="inventory-item-price"]').should('contain', '$');
    cy.get('[data-testid="inventory-item-price"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="inventory-item-price"]').should('contain', '$10');
    cy.get('[data-testid="inventory-item-price"]').should('contain', '$20');
    cy.get('[data-testid="inventory-item-price"]').should('contain', '$30');
    cy.get('[data-testid="inventory-item-price"]').should('contain', '$40');
    cy.get('[data-testid="inventory-item-price"]').should('contain', '$50');

    // Verify the first item is the cheapest
    cy.get('[data-testid="inventory-item-price"]').first().should('contain', '$10');
  });

  it('should handle edge case where no products are available', () => {
    // Intercept API call to get products
    cy.intercept('GET', '/api/products').as('getProducts');
    cy.wait('@getProducts');

    // Verify no products are returned
    cy.get('[data-testid="inventory-item-price"]').should('not.exist');

    // Click the sort dropdown and select "lohi" option
    cy.get('[data-testid="product-sort-container"]').click();
    cy.get('[data-testid="sort-option-lohi"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'No products found');

    // Verify sort button is still functional
    cy.get('[data-testid="sort-option-lohi"]').should('be.visible');
    cy.get('[data-testid="sort-option-lohi"]').click();

    // Verify error message disappears and products are displayed again
    cy.get('[data-testid="error-message"]').should('not.exist');
    cy.get('[data-testid="inventory-item-price"]').should('exist');
    cy.get('[data-testid="inventory-item-price"]').should('contain', '$10');
  });
});
